import { useMemo, useState } from 'react';
import { JxButton } from '@jinx-ui/react';

type Status = 'ok' | 'warning' | 'over';

type Project = {
  id: string;
  name: string;
  usage: number;
  status: Status;
};

const STATUS_LABEL: Record<Status, string> = {
  ok: 'В норме',
  warning: 'На грани',
  over: 'Перерасход',
};

const STATUS_COLOR: Record<Status, string> = {
  ok: 'var(--jx-color-success)',
  warning: 'var(--jx-color-warning)',
  over: 'var(--jx-color-danger)',
};

const STATUSES: Status[] = ['ok', 'warning', 'over'];

const PROJECTS: Project[] = [
  { id: 'atlas', name: 'Atlas Migration', usage: 42, status: 'ok' },
  { id: 'beacon', name: 'Beacon Analytics', usage: 88, status: 'warning' },
  { id: 'carbon', name: 'Carbon Billing', usage: 117, status: 'over' },
  { id: 'delta', name: 'Delta Search', usage: 23, status: 'ok' },
  { id: 'echo', name: 'Echo Notifications', usage: 91, status: 'warning' },
  { id: 'fjord', name: 'Fjord Data Lake', usage: 134, status: 'over' },
  { id: 'gamma', name: 'Gamma Rendering', usage: 57, status: 'ok' },
  { id: 'harbor', name: 'Harbor Registry', usage: 85, status: 'warning' },
  { id: 'indigo', name: 'Indigo Design Tokens', usage: 12, status: 'ok' },
  { id: 'juno', name: 'Juno Scheduler', usage: 104, status: 'over' },
  { id: 'kilo', name: 'Kilo Metrics', usage: 66, status: 'ok' },
  { id: 'lumen', name: 'Lumen CDN', usage: 94, status: 'warning' },
  { id: 'meridian', name: 'Meridian Auth', usage: 38, status: 'ok' },
  { id: 'nova', name: 'Nova Streaming', usage: 126, status: 'over' },
];

const PAGE_SIZE = 5;
const RADIUS = 18;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

function QuotaRing({ usage, status }: { usage: number; status: Status }) {
  const filled = Math.min(usage, 100);
  const offset = CIRCUMFERENCE * (1 - filled / 100);

  return (
    <svg
      width={48}
      height={48}
      viewBox="0 0 48 48"
      role="img"
      aria-label={`Квота израсходована на ${usage} процентов`}
      style={{ flexShrink: 0 }}
    >
      <circle
        cx={24}
        cy={24}
        r={RADIUS}
        fill="none"
        stroke="var(--jx-color-border)"
        strokeWidth={4}
      />
      <circle
        cx={24}
        cy={24}
        r={RADIUS}
        fill="none"
        stroke={STATUS_COLOR[status]}
        strokeWidth={4}
        strokeLinecap="round"
        strokeDasharray={CIRCUMFERENCE}
        strokeDashoffset={offset}
        transform="rotate(-90 24 24)"
      />
      <text
        x={24}
        y={24}
        textAnchor="middle"
        dominantBaseline="central"
        fontSize={12}
        fill="var(--jx-color-text)"
      >
        {usage}%
      </text>
    </svg>
  );
}

export default function ProjectSpendPanel() {
  const [selected, setSelected] = useState<Status[]>([]);
  const [page, setPage] = useState(0);

  const toggle = (status: Status) => {
    setSelected((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status],
    );
    setPage(0);
  };

  const reset = () => {
    setSelected([]);
    setPage(0);
  };

  const filtered = useMemo(
    () =>
      selected.length === 0
        ? PROJECTS
        : PROJECTS.filter((project) => selected.includes(project.status)),
    [selected],
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount - 1);
  const rows = filtered.slice(currentPage * PAGE_SIZE, currentPage * PAGE_SIZE + PAGE_SIZE);

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-4)',
        padding: 'var(--jx-space-4)',
        background: 'var(--jx-color-surface)',
        border: '1px solid var(--jx-color-border)',
        borderRadius: 'var(--jx-radius-lg)',
        color: 'var(--jx-color-text)',
      }}
    >
      <header style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-1)' }}>
        <h2 style={{ margin: 0 }}>Расход по проектам</h2>
        <p style={{ margin: 0, color: 'var(--jx-color-text-muted)' }}>
          Найдено проектов: {filtered.length}
        </p>
      </header>

      <div
        role="group"
        aria-label="Фильтр по статусу"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2)' }}
      >
        {STATUSES.map((status) => {
          const active = selected.includes(status);
          return (
            <button
              key={status}
              type="button"
              aria-pressed={active}
              onClick={() => toggle(status)}
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                gap: 'var(--jx-space-1)',
                padding: 'var(--jx-space-1) var(--jx-space-3)',
                borderRadius: 'var(--jx-radius-full)',
                border: `1px solid ${active ? STATUS_COLOR[status] : 'var(--jx-color-border)'}`,
                background: active ? 'var(--jx-color-surface-raised)' : 'transparent',
                color: active ? 'var(--jx-color-text)' : 'var(--jx-color-text-muted)',
                cursor: 'pointer',
                font: 'inherit',
              }}
            >
              <span
                aria-hidden="true"
                style={{
                  width: 8,
                  height: 8,
                  borderRadius: 'var(--jx-radius-full)',
                  background: STATUS_COLOR[status],
                }}
              />
              {STATUS_LABEL[status]}
              {active ? <span aria-hidden="true">×</span> : null}
            </button>
          );
        })}
      </div>

      {rows.length === 0 ? (
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            gap: 'var(--jx-space-3)',
            padding: 'var(--jx-space-6) var(--jx-space-4)',
            border: '1px dashed var(--jx-color-border)',
            borderRadius: 'var(--jx-radius-md)',
            textAlign: 'center',
          }}
        >
          <p style={{ margin: 0, fontWeight: 600 }}>Ни один проект не подходит под фильтры</p>
          <p style={{ margin: 0, color: 'var(--jx-color-text-muted)' }}>
            Снимите часть статусов, чтобы увидеть больше проектов.
          </p>
          <JxButton variant="primary" onClick={reset}>
            Сбросить фильтры
          </JxButton>
        </div>
      ) : (
        <>
          <ul
            style={{
              listStyle: 'none',
              margin: 0,
              padding: 0,
              display: 'flex',
              flexDirection: 'column',
              gap: 'var(--jx-space-2)',
            }}
          >
            {rows.map((project) => (
              <li
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 'var(--jx-space-3)',
                  padding: 'var(--jx-space-3)',
                  border: '1px solid var(--jx-color-border)',
                  borderRadius: 'var(--jx-radius-md)',
                }}
              >
                <QuotaRing usage={project.usage} status={project.status} />
                <span style={{ flex: 1, fontWeight: 600 }}>{project.name}</span>
                <span
                  style={{
                    padding: 'var(--jx-space-1) var(--jx-space-2)',
                    borderRadius: 'var(--jx-radius-sm)',
                    border: `1px solid ${STATUS_COLOR[project.status]}`,
                    color: STATUS_COLOR[project.status],
                    whiteSpace: 'nowrap',
                  }}
                >
                  {STATUS_LABEL[project.status]}
                </span>
              </li>
            ))}
          </ul>

          <nav
            aria-label="Постраничная навигация"
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              gap: 'var(--jx-space-3)',
            }}
          >
            <JxButton
              variant="secondary"
              disabled={currentPage === 0}
              onClick={() => setPage(currentPage - 1)}
            >
              Назад
            </JxButton>
            <span aria-live="polite" style={{ color: 'var(--jx-color-text-muted)' }}>
              Страница {currentPage + 1} из {pageCount}
            </span>
            <JxButton
              variant="secondary"
              disabled={currentPage >= pageCount - 1}
              onClick={() => setPage(currentPage + 1)}
            >
              Вперёд
            </JxButton>
          </nav>
        </>
      )}
    </section>
  );
}

